40	@InterfaceStability.Unstable
41	public final class Preconditions {
42	  private static final Logger LOG =
43	      LoggerFactory.getLogger(Preconditions.class);
44	
45	  private static final String VALIDATE_IS_NOT_NULL_EX_MESSAGE =
46	      "The argument object is NULL";
47	  private static final String CHECK_ARGUMENT_EX_MESSAGE =
48	      "The argument expression is false";
49	  private static final String CHECK_STATE_EX_MESSAGE =
