60	   * &quot;The validated object is null&quot;.</p>
61	   *
62	   * @param <T> the object type
63	   * @param obj  the object to check
64	   * @return the validated object
65	   * @throws NullPointerException if the object is {@code null}
66	   * @see #checkNotNull(Object, Object)
67	   */
68	  public static <T> T checkNotNull(final T obj) {
69	    return checkNotNull(obj, VALIDATE_IS_NOT_NULL_EX_MESSAGE);
70	  }
