94	   * <p>Preconditions that the specified argument is not {@code null},
95	   * throwing a NPE exception otherwise.
96	   *
97	   * <p>The message of the exception is {@code String.format(f, m)}.</p>
98	   *
99	   * @param <T> the object type
100	   * @param obj  the object to check
101	   * @param message  the {@link String#format(String, Object...)}
102	   *                 exception message if valid. Otherwise,
103	   *                 the message is {@link #VALIDATE_IS_NOT_NULL_EX_MESSAGE}
104	   * @param values  the optional values for the formatted exception message
105	   * @return the validated object
106	   * @throws NullPointerException if the object is {@code null}
107	   * @see #checkNotNull(Object, Supplier)
108	   */
109	  public static <T> T checkNotNull(final T obj, final String message,
110	      final Object... values) {
111	    // Deferring the evaluation of the message is a tradeoff between the cost
112	    // of constructing lambda Vs constructing a string object.
113	    // Using lambda would allocate an object on every call:
114	    //       return checkNotNull(obj, () -> String.format(message, values));
115	    if (obj == null) {
116	      String msg;
117	      try {
118	        msg = String.format(message, values);
119	      } catch (Exception e) {
