142	  public static <T> T checkNotNull(final T obj,
143	      final Supplier<String> msgSupplier) {
144	    if (obj == null) {
145	      String msg;
146	      try {
147	        // note that we can get NPE evaluating the message itself;
148	        // but we do not want this to override the actual NPE.
149	        msg = msgSupplier.get();
150	      } catch (Exception e) {
151	        // ideally we want to log the error to capture. This may cause log files
152	        // to bloat. On the other hand, swallowing the exception may hide a bug
153	        // in the caller. Debug level is a good compromise between the two
154	        // concerns.
155	        LOG.debug("Error formatting message", e);
156	        msg = VALIDATE_IS_NOT_NULL_EX_MESSAGE;
157	      }
