#!/usr/bin/env python3
"""Conservatively find unused single-type imports in java files."""
import os
import re
import sys

root = sys.argv[1]
imp_re = re.compile(r'^import\s+(static\s+)?([\w.]+)\.(\w+);\s*$')
word = re.compile(r'\b\w+\b')

unused = []
for dirpath, dirnames, filenames in os.walk(root):
    for fn in filenames:
        if not fn.endswith('.java'):
            continue
        p = os.path.join(dirpath, fn)
        with open(p, encoding='utf-8', errors='replace') as f:
            lines = f.readlines()
        import_lines = []
        body_words = set()
        for i, line in enumerate(lines):
            m = imp_re.match(line)
            if m:
                import_lines.append((i, m.group(2) + '.' + m.group(3), m.group(3)))
            else:
                body_words.update(word.findall(line))
        for i, fqn, simple in import_lines:
            if simple not in body_words:
                unused.append((p, i + 1, fqn))

for p, ln, fqn in unused:
    print(f"{p}:{ln}: {fqn}")
print(f"total: {len(unused)}", file=sys.stderr)

